 @Test void nativeAdjustmentsAndConfirmedPrefixDoNotResurrectSoldOrReturnedStock(){var f=fixture();assertEquals(200,apply(f,preview(f,event(f,1,10,0,null))).status());assertEquals(201,adjust(f.offer(),-3,1,key(),merchant).status());assertEquals(201,adjust(f.offer(),2,2,key(),merchant).status());
  var rows=db.queryForList("SELECT * FROM integration_stock_movements WHERE offer_id=? ORDER BY sequence",UUID.fromString(f.offer()));assertEquals(2,rows.size());assertEquals(-3L,rows.get(0).get("delta_qty"));assertEquals(2L,rows.get(1).get("delta_qty"));
  UUID ack=UUID.randomUUID();db.update("INSERT INTO integration_stock_acknowledgements VALUES (?,?,?,1,integration_prefix_hash(?,1),'SIMULATED_TEST',?,now())",ack,UUID.fromString(f.conn()),UUID.fromString(f.mapping()),UUID.fromString(f.mapping()),"TEST_ONLY_ACK_"+key());var next=preview(f,event(f,2,7,1,ack));assertEquals(200,next.status());assertEquals(9,next.data().get("target_on_hand_qty").asLong());assertEquals(0,next.data().get("delta_qty").asLong());assertEquals(200,apply(f,next).status());assertEquals(9,balance(f.offer()));assertEquals(2,db.queryForObject("SELECT count(*) FROM integration_stock_movements WHERE offer_id=?",Integer.class,UUID.fromString(f.offer())));
 }
 @Test void applyingSameSnapshotTwiceDoesNotCreateMoreInventory(){var f=fixture();var snap=preview(f,event(f,1,10,0,null));String k=key(),path=path(f)+"/inventory-previews/"+snap.id()+"/apply";var body=Map.of("accepted_snapshot_sha256",snap.data().get("snapshot_sha256").asString());var h=Map.of("Idempotency-Key",k,"X-Reverify-Token",proofFor("integration.stock.apply",merchant));var first=req("POST",path,body,merchant,h);assertEquals(200,first.status());assertEquals(first.id(),req("POST",path,body,merchant,h).id());assertEquals(409,apply(f,snap).status());assertEquals(10,balance(f.offer()));assertEquals(1,read(path(f)+"/inventory-applications",merchant).data().size());}
