 @Test void auditFailureRollsBackBalanceApplicationAndOneUseProof(){var f=fixture();var snap=preview(f,event(f,1,10,0,null));String token=proofFor("integration.stock.apply",merchant),k=key();var h=Map.of("Idempotency-Key",k,"X-Reverify-Token",token);String path=path(f)+"/inventory-previews/"+snap.id()+"/apply";var body=Map.of("accepted_snapshot_sha256",snap.data().get("snapshot_sha256").asString());db.execute("CREATE FUNCTION v32_reject_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.action='integration.stock.apply' THEN RAISE EXCEPTION 'TEST_ONLY_AUDIT_OUTAGE';END IF;RETURN NEW;END $$");db.execute("CREATE TRIGGER v32_reject_audit BEFORE INSERT ON audit_event FOR EACH ROW EXECUTE FUNCTION v32_reject_audit()");try{assertEquals(503,req("POST",path,body,merchant,h).status());assertEquals(0,balance(f.offer()));assertEquals(0,read(path(f)+"/inventory-applications",merchant).data().size());assertNull(db.queryForObject("SELECT used_at FROM reverify_grant WHERE token_hash=?",Timestamp.class,crypto.hash(token)));}finally{db.execute("DROP TRIGGER v32_reject_audit ON audit_event");db.execute("DROP FUNCTION v32_reject_audit()");}assertEquals(200,req("POST",path,body,merchant,h).status());assertEquals(10,balance(f.offer()));}
