 @Test void everyOperationCoversValidationAuthenticationScopeAndUnavailableBranches(){var f=fixture();UUID e=event(f,1,10,0,null);var snap=preview(f,e);String root=path(f);String noPermission=identity("MERCHANT",merchantId,List.of("offer.read"));
  record Operation(String method,String path,Object body,String action,long version){}
  var ops=List.of(new Operation("GET",prefix(),null,null,-1),new Operation("POST",prefix(),Map.of("label","TEST_ONLY_MATRIX","mode","SIMULATED_TEST","inventory_basis","DEDICATED_REMAINING_AFTER_WATERMARK","evidence_refs",List.of(evidence())),"integration.manage",-1),new Operation("PUT",root+"/state",Map.of("state","PAUSED","reason_code","OPERATOR_PAUSE"),"integration.manage",1),new Operation("GET",root+"/mappings",null,null,-1),new Operation("POST",root+"/mappings",Map.of("offer_id",f.offer(),"external_sku","TEST_ONLY_SKU","external_warehouse","TEST_ONLY_WH","unit","PIECE","evidence_refs",List.of(evidence())),"integration.mapping.write",1),new Operation("PUT",root+"/mappings/"+f.mapping()+"/state",Map.of("state","RETIRED","reason_code","TEST_SCENARIO_RETIRED"),"integration.mapping.write",0),new Operation("GET",root+"/inventory-events",null,null,-1),new Operation("POST",root+"/inventory-events/"+e+"/previews",Map.of(),null,-1),new Operation("POST",root+"/inventory-previews/"+snap.id()+"/apply",Map.of("accepted_snapshot_sha256",snap.data().get("snapshot_sha256").asString()),"integration.stock.apply",-1),new Operation("GET",root+"/inventory-applications",null,null,-1));
  for(var op:ops){var h=new HashMap<String,String>(Map.of("Idempotency-Key",key(),"If-Match","\""+Math.max(0,op.version())+"\""));if(op.action()!=null)h.put("X-Reverify-Token",proofFor(op.action(),merchant));assertEquals(400,req(op.method(),op.path().replace(store.toString(),"invalid"),op.body(),merchant,h).status(),op.path());assertEquals(401,req(op.method(),op.path(),op.body(),null,h).status(),op.path());assertEquals(403,req(op.method(),op.path(),op.body(),noPermission,h).status(),op.path());assertEquals(404,req(op.method(),op.path().replace(store.toString(),otherStore.toString()),op.body(),merchant,h).status(),op.path());}
  db.execute("ALTER TABLE integration_connections RENAME TO v32_connections_unavailable");try{for(var op:ops){var h=new HashMap<String,String>(Map.of("Idempotency-Key",key(),"If-Match","\""+Math.max(0,op.version())+"\""));if(op.action()!=null)h.put("X-Reverify-Token",proofFor(op.action(),merchant));assertEquals(503,req(op.method(),op.path(),op.body(),merchant,h).status(),op.path());}}finally{db.execute("ALTER TABLE v32_connections_unavailable RENAME TO integration_connections");}
 }
 @Test void rolePermissionRevocationAlsoBlocksCachedMutation(){var c=connect();UUID actor=db.queryForObject("SELECT principal_id FROM auth_session WHERE access_token_hash=?",UUID.class,crypto.hash(merchant));db.update("DELETE FROM principal_role WHERE principal_id=?",actor);assertEquals(403,read(prefix(),merchant).status());assertEquals(403,write("PUT",prefix()+"/"+c.id()+"/state",Map.of("state","ACTIVE","reason_code","TEST_SCENARIO_START"),merchant,"integration.manage",0,key()).status());}
 @Test void projectedNegativeOrOverflowQuantitiesAreBlockedWithNullTarget(){var f=fixture();assertEquals(201,adjust(f.offer(),1,0,key(),merchant).status());var s=preview(f,event(f,1,1000000000,0,null));assertFalse(s.data().get("eligible").asBoolean());assertTrue(s.data().get("target_on_hand_qty").isNull());assertEquals(409,apply(f,s).status());assertEquals(1,balance(f.offer()));}
 @Test void databaseRejectsMissingAndWrongPrefixAcknowledgements(){var f=fixture();assertEquals(201,adjust(f.offer(),1,0,key(),merchant).status());assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("INSERT INTO integration_stock_acknowledgements VALUES (?,?,?,1,?,'SIMULATED_TEST','TEST_ONLY_BAD',now())",UUID.randomUUID(),UUID.fromString(f.conn()),UUID.fromString(f.mapping()),"0".repeat(64)));assertThrows(org.springframework.dao.DataAccessException.class,()->event(f,1,10,1,null));assertEquals(0,read(path(f)+"/inventory-events",merchant).data().size());}
 @Test void paginationReturnsEachPersistedEventOnceAndRejectsInvalidCursor(){var f=fixture();event(f,1,10,0,null);event(f,2,11,0,null);var a=read(path(f)+"/inventory-events?limit=1",merchant);assertEquals(200,a.status());assertEquals(1,a.data().size());String cursor=a.body().get("page").get("next_cursor").asString();var b=read(path(f)+"/inventory-events?limit=1&cursor="+cursor,merchant);assertEquals(1,b.data().size());assertNotEquals(a.data().get(0).get("id"),b.data().get(0).get("id"));assertEquals(400,read(path(f)+"/inventory-events?cursor=invalid",merchant).status());}

 @Test void reservationVersionAndQuantityRemainProtectedDuringExternalApplication(){var f=fixture();assertEquals(200,apply(f,preview(f,event(f,1,10,0,null))).status());var e=event(f,2,4,0,null);var snap=preview(f,e);db.update("UPDATE inventory_balances SET reserved_qty=5,version=version+1 WHERE offer_id=?",UUID.fromString(f.offer()));assertEquals(409,apply(f,snap).status());var blocked=preview(f,e);assertFalse(blocked.data().get("eligible").asBoolean());assertTrue(blocked.data().get("blocked_reasons").toString().contains("RESERVED_STOCK_CONFLICT"));assertEquals(409,apply(f,blocked).status());assertEquals(10,balance(f.offer()));assertEquals(5,db.queryForObject("SELECT reserved_qty FROM inventory_balances WHERE offer_id=?",Integer.class,UUID.fromString(f.offer())));}
 @Test void concurrentPauseAndApplySerializeWithoutPartialStock()throws Exception{var f=fixture();var snap=preview(f,event(f,1,10,0,null));var pool=Executors.newFixedThreadPool(2);try{var start=new CountDownLatch(1);var a=pool.submit(()->{start.await();return apply(f,snap).status();});var b=pool.submit(()->{start.await();return write("PUT",path(f)+"/state",Map.of("state","PAUSED","reason_code","OPERATOR_PAUSE"),merchant,"integration.manage",1,key()).status();});start.countDown();int applied=a.get(20,TimeUnit.SECONDS);assertTrue(Set.of(200,409).contains(applied));assertEquals(200,b.get(20,TimeUnit.SECONDS));assertEquals(applied==200?10:0,balance(f.offer()));assertEquals(applied==200?1:0,read(path(f)+"/inventory-applications",merchant).data().size());}finally{pool.shutdownNow();}}
 @Test void factsAndHistoryCannotBeDeletedChangedOrTruncated(){var f=fixture();var e=event(f,1,10,0,null);var snap=preview(f,e);assertEquals(200,apply(f,snap).status());for(String table:List.of("integration_connections","integration_mappings","integration_inventory_events","integration_stock_previews","integration_stock_applications")){assertThrows(org.springframework.dao.DataAccessException.class,()->db.execute("DELETE FROM "+table));assertThrows(org.springframework.dao.DataAccessException.class,()->db.execute("TRUNCATE "+table+" CASCADE"));}assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("UPDATE integration_inventory_events SET external_remaining_qty=11 WHERE id=?",e));assertEquals(10,balance(f.offer()));}

 @Autowired org.springframework.transaction.support.TransactionTemplate transaction;
 @Test void revokedPermissionWhileWaitingForConnectionLockCannotApplyStaleActor()throws Exception{var f=fixture();var snap=preview(f,event(f,1,10,0,null));UUID actor=db.queryForObject("SELECT principal_id FROM auth_session WHERE access_token_hash=?",UUID.class,crypto.hash(merchant));var pool=Executors.newSingleThreadExecutor();var response=new java.util.concurrent.atomic.AtomicReference<Future<Response>>();try{transaction.executeWithoutResult(status->{db.queryForList("SELECT id FROM integration_connections WHERE id=? FOR UPDATE",UUID.fromString(f.conn()));response.set(pool.submit(()->apply(f,snap)));org.awaitility.Awaitility.await().atMost(Duration.ofSeconds(10)).until(()->db.queryForObject("SELECT count(*) FROM pg_stat_activity WHERE wait_event_type='Lock' AND query LIKE '%integration_connections%'",Integer.class)>0);db.update("DELETE FROM principal_role WHERE principal_id=?",actor);});assertEquals(403,response.get().get(20,TimeUnit.SECONDS).status());assertEquals(0,balance(f.offer()));assertEquals(0,db.queryForObject("SELECT count(*) FROM integration_stock_applications WHERE offer_id=?",Integer.class,UUID.fromString(f.offer())));}finally{pool.shutdownNow();}}
